ALTER TABLE hearth_economy.version DROP CONSTRAINT version_version_check;
ALTER TABLE hearth_economy.version ADD CONSTRAINT version_version_check CHECK(version BETWEEN 1 AND 8);
CREATE TABLE hearth_economy.housing_policy(realm_id uuid PRIMARY KEY REFERENCES hearth_economy.native_binding,geometry_hash text NOT NULL CHECK(length(geometry_hash)=64));
CREATE TABLE hearth_economy.housing_catalog(realm_id uuid REFERENCES hearth_economy.housing_policy,version text NOT NULL,hash text NOT NULL CHECK(length(hash)=64),payload text NOT NULL,PRIMARY KEY(realm_id,version));
CREATE TABLE hearth_economy.house(realm_id uuid NOT NULL REFERENCES hearth_economy.housing_policy,house_id uuid NOT NULL,owner_id uuid NOT NULL,version text NOT NULL,tier integer NOT NULL CHECK(tier>=0),width integer NOT NULL CHECK(width>=16),paid bigint NOT NULL CHECK(paid>=0),seed bigint NOT NULL,world_uuid uuid,phase text NOT NULL CHECK(phase IN ('PREPARING','APPLYING','ACTIVE')),revision bigint NOT NULL CHECK(revision>=0),PRIMARY KEY(realm_id,house_id),UNIQUE(realm_id,owner_id),UNIQUE(world_uuid),FOREIGN KEY(realm_id,owner_id) REFERENCES hearth_economy.account,FOREIGN KEY(realm_id,version) REFERENCES hearth_economy.housing_catalog);
CREATE TABLE hearth_economy.housing_request(realm_id uuid NOT NULL,request_id uuid NOT NULL,house_id uuid NOT NULL,owner_id uuid NOT NULL,version text NOT NULL,tier integer NOT NULL,cost bigint NOT NULL CHECK(cost>=0),revision bigint NOT NULL,paid boolean NOT NULL DEFAULT false,PRIMARY KEY(realm_id,request_id),FOREIGN KEY(realm_id,house_id) REFERENCES hearth_economy.house);
CREATE UNIQUE INDEX housing_one_pending ON hearth_economy.housing_request(realm_id,house_id) WHERE NOT paid;
CREATE TABLE hearth_economy.house_member(realm_id uuid NOT NULL,house_id uuid NOT NULL,player_id uuid NOT NULL,role text NOT NULL CHECK(role IN ('RESIDENT','VISITOR')),accepted boolean NOT NULL DEFAULT false,PRIMARY KEY(realm_id,house_id,player_id),FOREIGN KEY(realm_id,house_id) REFERENCES hearth_economy.house,FOREIGN KEY(realm_id,player_id) REFERENCES hearth_economy.account);
CREATE TABLE hearth_economy.housing_plot(realm_id uuid NOT NULL REFERENCES hearth_economy.housing_policy,player_id uuid NOT NULL,plot_id text NOT NULL,PRIMARY KEY(realm_id,player_id),UNIQUE(realm_id,plot_id),FOREIGN KEY(realm_id,player_id) REFERENCES hearth_economy.account);
